1	import {
2	    CdkDragDrop,
3	    DragDropModule,
4	    moveItemInArray,
5	} from '@angular/cdk/drag-drop';
6	import {
7	    Component,
8	    effect,
9	    inject,
10	    input,
11	    output,
12	    signal,
13	} from '@angular/core';
14	import { toSignal } from '@angular/core/rxjs-interop';
15	import { MatDialog } from '@angular/material/dialog';
16	import { MatInputModule } from '@angular/material/input';
17	import { MatSnackBar } from '@angular/material/snack-bar';
18	import { Router } from '@angular/router';
19	import { Store } from '@ngrx/store';
20	import { TranslateService } from '@ngx-translate/core';
21	import { PlaylistContextFacade } from '@iptvnator/playlist/shared/util';
22	import {
23	    PlaylistActions,
24	    selectActiveTypeFilters,
25	    selectAllPlaylistsMeta,
26	    selectPlaylistsLoadingFlag,
27	} from 'm3u-state';
28	import { BehaviorSubject, combineLatest, map } from 'rxjs';
29	import { DialogService } from 'components';
30	import {
31	    DatabaseService,
32	    DataService,
33	    DbOperationEvent,
34	    isDbAbortError,
35	    PlaybackPositionService,
36	    PlaylistRefreshService,
37	    SortBy,
38	    SortService,
39	    XtreamPendingRestoreService,
40	} from 'services';
41	import {
42	    PLAYLIST_UPDATE,
43	    PlaylistMeta,
44	    PlaylistRefreshEvent,
45	} from 'shared-interfaces';
46	
47	import { EmptyStateComponent } from './empty-state/empty-state.component';
48	import { PlaylistInfoComponent } from './playlist-info/playlist-info.component';
49	import { PlaylistItemComponent } from './playlist-item/playlist-item.component';
50	
51	type PlaylistBusyOperation = {
52	    current?: number;
53	    operation: string;
54	    operationId?: string;
55	    phase?: string;
56	    status: DbOperationEvent['status'];
57	    total?: number;
58	};
59	
60	@Component({
61	    selector: 'app-recent-playlists',
62	    templateUrl: './recent-playlists.component.html',
63	    styleUrls: ['./recent-playlists.component.scss'],
64	    imports: [
65	        DragDropModule,
66	        EmptyStateComponent,
67	        MatInputModule,
68	        PlaylistItemComponent,
69	    ],
70	})
71	export class RecentPlaylistsComponent {
72	    private readonly databaseService = inject(DatabaseService);
73	    private readonly dialog = inject(MatDialog);
74	    private readonly dialogService = inject(DialogService);
75	    private readonly dataService = inject(DataService);
76	    private readonly playbackPositionService = inject(PlaybackPositionService);
77	    private readonly playlistRefreshService = inject(PlaylistRefreshService);
78	    private readonly router = inject(Router);
79	    private readonly snackBar = inject(MatSnackBar);
80	    private readonly sortService = inject(SortService);
81	    private readonly store = inject(Store);
82	    private readonly translate = inject(TranslateService);
83	    private readonly playlistContext = inject(PlaylistContextFacade);
84	    private readonly pendingRestoreService = inject(
85	        XtreamPendingRestoreService
86	    );
87	
88	    readonly sidebarMode = input(false);
89	    readonly searchQueryInput = input<string>('');
90	    readonly playlistClicked = output<string>();
91	    readonly addPlaylistClicked = output<void>();
92	
93	    readonly allPlaylistsLoaded = this.store.selectSignal(
94	        selectPlaylistsLoadingFlag
95	    );
96	    readonly activePlaylistId = this.playlistContext.resolvedPlaylistId;
97	
98	    private readonly currentSortOptions = toSignal(
99	        this.sortService.getSortOptions(),
100	        { requireSync: true }
101	    );
102	
103	    readonly isCustomSortActive = () =>
104	        this.currentSortOptions().by === SortBy.CUSTOM;
105	
106	    readonly searchQuery = new BehaviorSubject<string>('');
107	    readonly pendingDeletionIds = signal<Set<string>>(new Set());
108	    readonly pendingRefreshIds = signal<Set<string>>(new Set());
109	    readonly busyOperations = signal<Map<string, PlaylistBusyOperation>>(
110	        new Map()
111	    );
112	
113	    constructor() {
114	        // Update searchQuery when input changes
115	        effect(() => {
116	            this.searchQuery.next(this.searchQueryInput());
117	        });
118	    }
119	
120	    readonly playlistsData$ = combineLatest([
121	        this.store.select(selectAllPlaylistsMeta),
122	        this.searchQuery,
123	        this.store.select(selectActiveTypeFilters),
124	        this.sortService.getSortOptions(),
125	    ]).pipe(
126	        map(([playlists, searchQuery, filters, sortOptions]) => {
127	            const filteredPlaylists = playlists
128	                .filter((item) => {
129	                    const isStalkerFilter =
130	                        item.macAddress && filters.includes('stalker');
131	                    const isXtreamFilter =
132	                        item.username &&
133	                        item.password &&
134	                        item.serverUrl &&
135	                        filters.includes('xtream');
136	                    const isM3uFilter =
137	                        !item.username &&
138	                        !item.password &&
139	                        !item.serverUrl &&
140	                        !item.macAddress &&
141	                        filters.includes('m3u');
142	
143	                    return (
144	                        (isStalkerFilter && filters.includes('stalker')) ||
145	                        (isXtreamFilter && filters.includes('xtream')) ||
146	                        (isM3uFilter && filters.includes('m3u'))
147	                    );
148	                })
149	                .filter((item) =>
150	                    (item.title || '')
151	                        .toLowerCase()
152	                        .includes(searchQuery.toLowerCase())
153	                );
154	
155	            // Apply sorting using the SortService
156	            const sortedPlaylists = this.sortService.sortPlaylists(
157	                filteredPlaylists,
158	                sortOptions
159	            );
160	
161	            return {
162	                playlists: sortedPlaylists,
163	                totalCount: playlists.length,
164	            };
165	        })
166	    );
167	
168	    readonly playlistsData = toSignal(this.playlistsData$, {
169	        initialValue: {
170	            playlists: [] as PlaylistMeta[],
171	            totalCount: 0,
172	        },
173	    });
174	
175	    /**
176	     * Opens the details dialog with the information about the provided playlist
177	     * @param data selected playlist
178	     */
179	    openInfoDialog(data: PlaylistMeta): void {
180	        this.dialog.open(PlaylistInfoComponent, {
181	            data,
182	        });
183	    }
184	
185	    /**
186	     * Drop event handler - applies the new sort order to the playlists array
187	     * @param event drop event
188	     */
189	    drop(event: CdkDragDrop<PlaylistMeta[]>, playlists: PlaylistMeta[]): void {
190	        moveItemInArray(playlists, event.previousIndex, event.currentIndex);
191	        this.store.dispatch(
192	            PlaylistActions.updatePlaylistPositions({
193	                positionUpdates: playlists.map((item, index) => ({
194	                    id: item._id,
195	                    changes: { position: index },
196	                })),
197	            })
198	        );
199	    }
200	
201	    onAddPlaylist() {
202	        this.addPlaylistClicked.emit();
203	    }
204	
205	    getPlaylist(playlistMeta: PlaylistMeta): void {
206	        if (playlistMeta.serverUrl) {
207	            this.router.navigate(['/workspace', 'xtreams', playlistMeta._id]);
208	        } else if (playlistMeta.macAddress) {
209	            this.router.navigate(['/workspace', 'stalker', playlistMeta._id]);
210	        } else {
211	            this.router.navigate(['/workspace', 'playlists', playlistMeta._id]);
212	            this.playlistClicked.emit(playlistMeta._id);
213	        }
214	    }
215	
216	    /**
217	     * Triggers on remove click
218	     * @param playlistId playlist id to remove
219	     */
220	    removeClicked(item: PlaylistMeta): void {
221	        if (this.isDeletePending(item._id) || this.isRefreshPending(item._id)) {
222	            return;
223	        }
224	
225	        this.dialogService.openConfirmDialog({
226	            title: this.translate.instant('HOME.PLAYLISTS.REMOVE_DIALOG.TITLE'),
227	            message: this.translate.instant(
228	                'HOME.PLAYLISTS.REMOVE_DIALOG.MESSAGE'
229	            ),
230	            onConfirm: () => {
231	                this.removePlaylist(item);
232	            },
233	        });
234	    }
235	
236	    /**
237	     * Removes the provided playlist from the database
238	     * @param playlistId playlist id to remove
239	     */
240	    async removePlaylist(item: PlaylistMeta) {
241	        if (this.isDeletePending(item._id) || this.isRefreshPending(item._id)) {
242	            return;
243	        }
244	
245	        this.setPendingDeletion(item._id, true);
246	        const operationId = item.serverUrl
247	            ? this.databaseService.createOperationId('playlist-delete')
248	            : undefined;
249	
250	        try {
251	            const deleted = await this.databaseService.deletePlaylist(
252	                item._id,
253	                operationId
254	                    ? {
255	                          operationId,
256	                          onEvent: (event) =>
257	                              this.updateBusyOperation(item._id, event),
258	                      }
259	                    : undefined
260	            );
261	            if (deleted) {
262	                this.store.dispatch(
263	                    PlaylistActions.removePlaylist({ playlistId: item._id })
264	                );
265	                this.snackBar.open(
266	                    this.translate.instant(
267	                        'HOME.PLAYLISTS.REMOVE_DIALOG.SUCCESS'
268	                    ),
269	                    undefined,
270	                    {
271	                        duration: 2000,
272	                    }
273	                );
274	            }
275	        } finally {
276	            this.clearBusyOperation(item._id);
277	            this.setPendingDeletion(item._id, false);
278	        }
279	    }
280	
281	    /**
282	     * Sends an IPC event with the playlist details to the main process to trigger the refresh operation
283	     * @param item playlist to update
284	     */
285	    refreshPlaylist(item: PlaylistMeta) {
286	        if (this.isDeletePending(item._id) || this.isRefreshPending(item._id)) {
287	            return;
288	        }
289	
290	        if (item.serverUrl) {
291	            // For Xtream playlists, delete and re-import
292	            this.refreshXtreamPlaylist(item);
293	        } else if (window.electron && (item.url || item.filePath)) {
294	            void this.refreshM3uPlaylist(item);
295	        } else {
296	            // For M3U playlists, use existing refresh logic
297	            this.dataService.sendIpcEvent(PLAYLIST_UPDATE, {
298	                id: item._id,
299	                title: item.title,
300	                ...(item.url ? { url: item.url } : { filePath: item.filePath }),
301	            });
302	        }
303	    }
304	
305	    /**
306	     * Refresh Xtream playlist by deleting all data and re-importing from remote
307	     * @param item Xtream playlist to refresh
308	     */
309	    async refreshXtreamPlaylist(item: PlaylistMeta) {
310	        if (this.isDeletePending(item._id) || this.isRefreshPending(item._id)) {
311	            return;
312	        }
313	
314	        this.dialogService.openConfirmDialog({
315	            title: this.translate.instant(
316	                'HOME.PLAYLISTS.REFRESH_XTREAM_DIALOG.TITLE'
317	            ),
318	            message: this.translate.instant(
319	                'HOME.PLAYLISTS.REFRESH_XTREAM_DIALOG.MESSAGE'
320	            ),
321	            onConfirm: async () => {
322	                if (
323	                    this.isDeletePending(item._id) ||
324	                    this.isRefreshPending(item._id)
325	                ) {
326	                    return;
327	                }
328	
329	                this.setPendingRefresh(item._id, true);
330	                const operationId =
331	                    this.databaseService.createOperationId('xtream-refresh');
332	
333	                try {
334	                    // Show immediate feedback — deletion can take several seconds
335	                    // for large playlists.
336	                    this.snackBar.open(
337	                        this.translate.instant(
338	                            'HOME.PLAYLISTS.REFRESH_XTREAM_DIALOG.STARTED'
339	                        ),
340	                        undefined,
341	                        { duration: 2000 }
342	                    );
343	
344	                    // Delete content/categories and update the timestamp in
345	                    // parallel — both operations are fully independent.
346	                    const updateDate = Date.now();
347	                    const [restoreState, playbackPositions] = await Promise.all(
348	                        [
349	                            this.databaseService.deleteXtreamPlaylistContent(
350	                                item._id,
351	                                {
352	                                    operationId,
353	                                    onEvent: (workerEvent) =>
354	                                        this.updateBusyOperation(
355	                                            item._id,
356	                                            workerEvent
357	                                        ),
358	                                }
359	                            ),
360	                            this.playbackPositionService.getAllPlaybackPositions(
361	                                item._id
362	                            ),
363	                            this.databaseService.updateXtreamPlaylistDetails({
364	                                id: item._id,
365	                                updateDate,
366	                            }),
367	                        ]
368	                    );
369	
370	                    this.pendingRestoreService.set(item._id, {
371	                        ...restoreState,
372	                        playbackPositions,
373	                    });
374	
375	                    // Update the timestamp in NgRx / IndexedDB
376	                    this.store.dispatch(
377	                        PlaylistActions.updatePlaylistMeta({
378	                            playlist: { ...item, updateDate },
379	                        })
380	                    );
381	
382	                    // Navigate to the playlist to trigger re-import
383	                    this.router.navigate(['/workspace', 'xtreams', item._id]);
384	                } catch (error) {
385	                    if (!isDbAbortError(error)) {
386	                        console.error(
387	                            'Error refreshing Xtream playlist:',
388	                            error
389	                        );
390	                        this.snackBar.open(
391	                            this.translate.instant(
392	                                'HOME.PLAYLISTS.REFRESH_XTREAM_DIALOG.ERROR'
393	                            ),
394	                            undefined,
395	                            { duration: 3000 }
396	                        );
397	                    }
398	                } finally {
399	                    this.clearBusyOperation(item._id);
400	                    this.setPendingRefresh(item._id, false);
401	                }
402	            },
403	        });
404	    }
405	
406	    private async refreshM3uPlaylist(item: PlaylistMeta): Promise<void> {
407	        if (this.isDeletePending(item._id) || this.isRefreshPending(item._id)) {
408	            return;
409	        }
410	
411	        this.setPendingRefresh(item._id, true);
412	        const operationId =
413	            this.databaseService.createOperationId('playlist-refresh');
414	
415	        try {
416	            const refreshedPlaylist =
417	                await this.playlistRefreshService.refreshPlaylist(
418	                    {
419	                        operationId,
420	                        playlistId: item._id,
421	                        title: item.title,
422	                        url: item.url,
423	                        filePath: item.filePath,
424	                    },
425	                    {
426	                        onEvent: (event) =>
427	                            this.updateBusyOperation(
428	                                item._id,
429	                                this.toPlaylistRefreshBusyEvent(event)
430	                            ),
431	                    }
432	                );
433	
434	            this.updateBusyOperation(item._id, {
435	                operationId,
436	                operation: 'playlist-refresh',
437	                playlistId: item._id,
438	                phase: 'saving',
439	                status: 'progress',
440	            });
441	
442	            this.store.dispatch(
443	                PlaylistActions.updatePlaylist({
444	                    playlist: {
445	                        ...refreshedPlaylist,
446	                        _id: item._id,
447	                    },
448	                    playlistId: item._id,
449	                })
450	            );
451	
452	            this.clearBusyOperation(item._id);
453	            this.snackBar.open(
454	                this.translate.instant(
455	                    'HOME.PLAYLISTS.PLAYLIST_UPDATE_SUCCESS'
456	                ),
457	                null,
458	                { duration: 2000 }
459	            );
460	        } catch (error) {
461	            if (!isDbAbortError(error)) {
462	                console.error('Error refreshing playlist:', error);
463	                this.snackBar.open(
464	                    this.getPlaylistRefreshErrorMessage(error, item),
465	                    this.translate.instant('CLOSE'),
466	                    { duration: 5000 }
467	                );
468	            }
469	        } finally {
470	            this.clearBusyOperation(item._id);
471	            this.setPendingRefresh(item._id, false);
472	        }
473	    }
474	
475	    isDeletePending(playlistId: string): boolean {
476	        return this.pendingDeletionIds().has(playlistId);
477	    }
478	
479	    isRefreshPending(playlistId: string): boolean {
480	        return this.pendingRefreshIds().has(playlistId);
481	    }
482	
483	    getBusyMessage(item: PlaylistMeta): string {
484	        const operation = this.busyOperations().get(item._id);
485	        if (!operation) {
486	            return '';
487	        }
488	
489	        switch (operation.operation) {
490	            case 'delete-playlist':
491	                return this.translateDeletePhase(operation.phase);
492	            case 'delete-xtream-content':
493	                return this.translateRefreshPhase(operation.phase);
494	            case 'playlist-refresh':
495	                return this.translatePlaylistRefreshPhase(operation.phase);
496	            default:
497	                return '';
498	        }
499	    }
500	
501	    getBusyProgress(playlistId: string): number | null {
502	        const operation = this.busyOperations().get(playlistId);
503	        if (
504	            !operation ||
505	            operation.current == null ||
506	            operation.total == null ||
507	            operation.total <= 0
508	        ) {
509	            return null;
510	        }
511	
512	        return Math.min(
513	            100,
514	            Math.round((operation.current / operation.total) * 100)
515	        );
516	    }
517	
518	    canCancelBusyOperation(item: PlaylistMeta): boolean {
519	        const operation = this.busyOperations().get(item._id);
520	        if (!operation?.operationId) {
521	            return false;
522	        }
523	
524	        if (operation.operation === 'playlist-refresh') {
525	            return true;
526	        }
527	
528	        return Boolean(item.serverUrl);
529	    }
530	
531	    async cancelBusyOperation(item: PlaylistMeta): Promise<void> {
532	        const operation = this.busyOperations().get(item._id);
533	        if (!operation?.operationId) {
534	            return;
535	        }
536	
537	        if (operation.operation === 'playlist-refresh') {
538	            await this.playlistRefreshService.cancelRefresh(
539	                operation.operationId
540	            );
541	            return;
542	        }
543	
544	        await this.databaseService.cancelOperation(operation.operationId);
545	    }
546	
547	    private setPendingDeletion(playlistId: string, isPending: boolean): void {
548	        this.pendingDeletionIds.update((current) => {
549	            const next = new Set(current);
550	            if (isPending) {
551	                next.add(playlistId);
552	            } else {
553	                next.delete(playlistId);
554	            }
555	            return next;
556	        });
557	    }
558	
559	    private setPendingRefresh(playlistId: string, isPending: boolean): void {
560	        this.pendingRefreshIds.update((current) => {
561	            const next = new Set(current);
562	            if (isPending) {
563	                next.add(playlistId);
564	            } else {
565	                next.delete(playlistId);
566	            }
567	            return next;
568	        });
569	    }
570	
571	    private updateBusyOperation(
572	        playlistId: string,
573	        event: DbOperationEvent
574	    ): void {
575	        this.busyOperations.update((current) => {
576	            const next = new Map(current);
577	
578	            if (
579	                event.status === 'completed' ||
580	                event.status === 'cancelled' ||
581	                event.status === 'error'
582	            ) {
583	                next.delete(playlistId);
584	                return next;
585	            }
586	
587	            next.set(playlistId, {
588	                operation: event.operation,
589	                operationId: event.operationId,
590	                phase: event.phase,
591	                current: event.current,
592	                total: event.total,
593	                status: event.status,
594	            });
595	            return next;
596	        });
597	    }
598	
599	    private clearBusyOperation(playlistId: string): void {
600	        this.busyOperations.update((current) => {
601	            const next = new Map(current);
602	            next.delete(playlistId);
603	            return next;
604	        });
605	    }
606	
607	    private toPlaylistRefreshBusyEvent(
608	        event: PlaylistRefreshEvent
609	    ): DbOperationEvent {
610	        return {
611	            operationId: event.operationId,
612	            operation: 'playlist-refresh',
613	            playlistId: event.playlistId,
614	            phase: event.phase,
615	            status: event.status,
616	            error: event.error,
617	        };
618	    }
619	
620	    private translateDeletePhase(phase?: string): string {
621	        switch (phase) {
622	            case 'deleting-favorites':
623	                return this.translate.instant(
624	                    'HOME.PLAYLISTS.REMOVE_DIALOG.DELETING_FAVORITES'
625	                );
626	            case 'deleting-recently-viewed':
627	                return this.translate.instant(
628	                    'HOME.PLAYLISTS.REMOVE_DIALOG.DELETING_RECENT'
629	                );
630	            case 'deleting-playback-positions':
631	                return this.translate.instant(
632	                    'HOME.PLAYLISTS.REMOVE_DIALOG.DELETING_PROGRESS'
633	                );
634	            case 'deleting-downloads':
635	                return this.translate.instant(
636	                    'HOME.PLAYLISTS.REMOVE_DIALOG.DELETING_DOWNLOADS'
637	                );
638	            case 'deleting-content':
639	                return this.translate.instant(
640	                    'HOME.PLAYLISTS.REMOVE_DIALOG.DELETING_CONTENT'
641	                );
642	            case 'deleting-categories':
643	                return this.translate.instant(
644	                    'HOME.PLAYLISTS.REMOVE_DIALOG.DELETING_CATEGORIES'
645	                );
646	            case 'deleting-playlist':
647	                return this.translate.instant(
648	                    'HOME.PLAYLISTS.REMOVE_DIALOG.DELETING_PLAYLIST'
649	                );
650	            default:
651	                return this.translate.instant(
652	                    'HOME.PLAYLISTS.REMOVE_DIALOG.IN_PROGRESS'
653	                );
654	        }
655	    }
656	
657	    private translateRefreshPhase(phase?: string): string {
658	        switch (phase) {
659	            case 'collecting-user-data':
660	                return this.translate.instant(
661	                    'HOME.PLAYLISTS.REFRESH_XTREAM_DIALOG.COLLECTING_DATA'
662	                );
663	            case 'deleting-content':
664	                return this.translate.instant(
665	                    'HOME.PLAYLISTS.REFRESH_XTREAM_DIALOG.DELETING_CONTENT'
666	                );
667	            case 'deleting-categories':
668	                return this.translate.instant(
669	                    'HOME.PLAYLISTS.REFRESH_XTREAM_DIALOG.DELETING_CATEGORIES'
670	                );
671	            default:
672	                return this.translate.instant(
673	                    'HOME.PLAYLISTS.REFRESH_XTREAM_DIALOG.IN_PROGRESS'
674	                );
675	        }
676	    }
677	
678	    private translatePlaylistRefreshPhase(phase?: string): string {
679	        switch (phase) {
680	            case 'fetching':
681	                return this.translateWithFallback(
682	                    'HOME.PLAYLISTS.REFRESH_FETCHING',
683	                    'Fetching playlist...'
684	                );
685	            case 'reading-file':
686	                return this.translateWithFallback(
687	                    'HOME.PLAYLISTS.REFRESH_READING_FILE',
688	                    'Reading playlist file...'
689	                );
690	            case 'parsing':
691	                return this.translateWithFallback(
692	                    'HOME.PLAYLISTS.REFRESH_PARSING',
693	                    'Parsing playlist...'
694	                );
695	            case 'saving':
696	                return this.translateWithFallback(
697	                    'HOME.PLAYLISTS.REFRESH_SAVING',
698	                    'Saving playlist...'
699	                );
700	            default:
701	                return this.translate.instant('HOME.PLAYLISTS.REFRESH');
702	        }
703	    }
704	
705	    private getPlaylistRefreshErrorMessage(
706	        error: unknown,
707	        item: PlaylistMeta
708	    ): string {
709	        if (item.filePath) {
710	            const message = String(
711	                (error as { message?: string })?.message ?? error
712	            );
713	
714	            if (/(ENOENT|no such file or directory|not found)/i.test(message)) {
