35	export class WorkspaceDashboardComponent {
36	    private readonly translate = inject(TranslateService);
37	
38	    readonly editMode = signal(false);
39	    private readonly languageTick = toSignal(
40	        this.translate.onLangChange.pipe(startWith(null)),
41	        { initialValue: null }
42	    );
43	    private readonly sizeOrder: DashboardWidgetSize[] = [
44	        'one-third',
45	        'half',
