489	        return this.getActivityItemTypeLabel(item);
490	    }
491	
492	    getRecentlyAddedItemTypeLabel(item: DashboardRecentlyAddedItem): string {
493	        return this.getActivityItemTypeLabel(item);
494	    }
495	
496	    private getActivityItemTypeLabel(
497	        item: Pick<PortalActivityItem, 'type'>
498	    ): string {
499	        this.languageTick();
500	        return this.translateText(getActivityTypeLabelKey(item.type));
501	    }
502	
503	    getGlobalFavoriteLink(item: DashboardFavoriteItem): string[] {
504	        return getGlobalFavoriteNavigation(item).link;
505	    }
506	
507	    getGlobalFavoriteNavigationState(
508	        item: DashboardFavoriteItem
509	    ): WorkspaceNavigationTarget['state'] {
