525	                }),
526	            }).link;
527	        }
528	
529	        return buildXtreamNavigationTarget({
530	            playlistId: item.playlist_id,
531	            type: item.type,
532	            categoryId: item.category_id,
533	            itemId: item.xtream_id,
534	            title: item.title,
535	            imageUrl: item.poster_url,
536	        }).link;
537	    }
538	
539	    getRecentlyAddedNavigationState(
540	        item: DashboardRecentlyAddedItem
541	    ): WorkspaceNavigationTarget['state'] {
542	        if (item.source === 'stalker' && item.type !== 'live') {
543	            return buildStalkerDetailNavigationTarget({
544	                playlistId: item.playlist_id,
545	                type: item.type,
546	                categoryId: item.category_id,
547	                item: buildStalkerStateItem(item.stalker_item, {
548	                    id: item.id,
549	                    title: item.title,
550	                    type: item.type,
551	                    category_id: item.category_id,
552	                    poster_url: item.poster_url,
553	                }),
554	            }).state;
555	        }
556	
