578	            const playlist = this.playlists().find(
579	                (p) => p._id === item.playlist_id
580	            );
581	            if (!playlist) return;
582	
583	            const currentFavorites = Array.isArray(playlist.favorites)
584	                ? [...playlist.favorites]
585	                : [];
586	            const itemMatchStr = String(item.id);
587	
588	            const filteredFavorites = currentFavorites.filter(
589	                (raw, index) =>
590	                    !stalkerItemMatchesId(
591	                        raw,
592	                        itemMatchStr,
593	                        playlist._id,
594	                        index
595	                    )
596	            );
597	
598	            this.store.dispatch(
599	                PlaylistActions.updatePlaylistMeta({
600	                    playlist: {
601	                        _id: item.playlist_id,
602	                        favorites: filteredFavorites,
603	                    } as unknown as PlaylistMeta,
604	                }) as any
605	            );
606	        }
607	
608	        if (item.source === 'm3u') {
609	            const playlist = await firstValueFrom(
610	                this.playlistsService.getPlaylistById(item.playlist_id)
611	            );
612	            const currentFavorites = Array.isArray(playlist?.favorites)
613	                ? playlist.favorites.filter(
614	                      (favorite): favorite is string =>
615	                          typeof favorite === 'string'
616	                  )
617	                : [];
618	            const filteredFavorites = currentFavorites.filter(
619	                (favorite) => favorite !== String(item.id)
620	            );
621	
622	            await firstValueFrom(
623	                this.playlistsService.setFavorites(
624	                    item.playlist_id,
625	                    filteredFavorites
626	                )
627	            );
