631	
632	    formatTimestamp(value?: string | number): string {
633	        this.languageTick();
634	
635	        const timestamp = toTimestamp(value);
636	        if (!timestamp) {
637	            return this.translateText('WORKSPACE.DASHBOARD.NOT_YET_SYNCED');
638	        }
639	
640	        return new Date(timestamp).toLocaleString(this.getLocale());
641	    }
