643	    private async loadM3uPlaylistFavorites(
644	        playlistMeta: PlaylistMeta
645	    ): Promise<DashboardFavoriteItem[]> {
646	        const playlist = (await firstValueFrom(
647	            this.playlistsService.getPlaylistById(playlistMeta._id)
648	        )) as Playlist & {
649	            playlist?: {
650	                items?: Channel[];
651	            };
652	        };
653	        const favorites = Array.isArray(playlist?.favorites)
654	            ? playlist.favorites.filter(
655	                  (favorite): favorite is string =>
656	                      typeof favorite === 'string' && favorite.trim().length > 0
657	              )
658	            : [];
659	
660	        if (favorites.length === 0) {
661	            return [];
662	        }
663	
664	        const items: Channel[] = Array.isArray(playlist?.playlist?.items)
665	            ? (playlist.playlist.items as Channel[])
666	            : [];
667	        const fallbackTimestamp =
668	            this.getM3uFavoriteTimestamp(playlistMeta) ??
669	            new Date(0).toISOString();
670	
671	        return items.reduce<DashboardFavoriteItem[]>((acc, channel) => {
672	            const channelId = String(channel.id ?? '').trim();
673	            const channelUrl = String(channel.url ?? '').trim();
674	            const matchedFavoriteId = favorites.find(
675	                (favorite) => favorite === channelId || favorite === channelUrl
676	            );
677	
678	            if (!matchedFavoriteId) {
679	                return acc;
680	            }
681	
682	            acc.push({
683	                id: matchedFavoriteId,
684	                title: channel.name?.trim() || channel.tvg?.name || channelId,
685	                type: 'live',
686	                playlist_id: playlistMeta._id,
687	                playlist_name:
688	                    playlistMeta.title || playlistMeta.filename || 'M3U',
689	                added_at: fallbackTimestamp,
690	                category_id: 'live',
691	                xtream_id: matchedFavoriteId,
692	                poster_url: channel.tvg?.logo || undefined,
693	                source: 'm3u',
694	            });
695	            return acc;
696	        }, []);
697	    }
