699	    private getM3uFavoriteTimestamp(playlist: PlaylistMeta): string | null {
700	        if (playlist.updateDate) {
701	            return new Date(playlist.updateDate).toISOString();
702	        }
703	
704	        return typeof playlist.importDate === 'string'
705	            ? playlist.importDate
706	            : null;
