30	    readonly emptyHint = input<string>();
31	    readonly emptyActionLabel = input<string>();
32	    readonly emptyActionLink = input<string[]>();
33	    readonly viewMode = input<DashboardActivityViewMode>('list');
34	    readonly showRemoveAction = input(false);
35	    readonly removeActionLabel = input('');
36	
37	    @Output() readonly itemAction =
38	        new EventEmitter<DashboardActivityItemViewModel>();
39	
