41	
42	    hasImage(item: DashboardActivityItemViewModel): boolean {
43	        if (!item.imageUrl) {
44	            return false;
45	        }
46	
47	        return !this.failedImages()[item.id];
48	    }
49	
50	    markImageAsFailed(itemId: string): void {
51	        this.failedImages.update((state) => {
52	            if (state[itemId]) {
53	                return state;
54	            }
55	
56	            return {
57	                ...state,
58	                [itemId]: true,
59	            };
60	        });
61	    }
62	
63	    getFallbackIcon(item: DashboardActivityItemViewModel): string {
64	        if (item.type === 'live') {
65	            return 'live_tv';
66	        }
67	
68	        if (item.type === 'series') {
