76	        const target = event.target as HTMLElement | null;
77	        if (!target) {
78	            return;
79	        }
80	
81	        const remaining =
82	            target.scrollHeight - target.scrollTop - target.clientHeight;
83	        if (remaining <= 120) {
84	            this.scrolledToEnd.emit();
85	        }
86	    }
87	
88	    onActionClick(event: Event, item: DashboardActivityItemViewModel): void {
89	        event.preventDefault();
90	        event.stopPropagation();
91	        this.itemAction.emit(item);
92	    }
93	}
