:host {
    display: block;
    --rail-card-width: 168px;
    --rail-gap: 12px;
    --rail-radius: 14px;
}

.rail {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.rail__header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    padding: 0 4px;
}

.rail__title {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: var(--mat-sys-on-surface);
}

.rail__see-all {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    font-size: 0.8rem;
    color: var(--mat-sys-on-surface-variant);
    text-decoration: none;
    opacity: 0.7;
    transition: opacity 0.15s ease;

    mat-icon {
        font-size: 18px;
        width: 18px;
        height: 18px;
    }

    &:hover {
        opacity: 1;
        color: var(--mat-sys-primary);
    }
}

.rail__viewport {
    position: relative;
    min-width: 0;

    &:hover .rail__chev--visible {
        opacity: 1;
        pointer-events: auto;
    }
}

.rail__track {
    display: flex;
    gap: var(--rail-gap);
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x mandatory;
    scroll-padding-inline-start: 4px;
    scrollbar-width: none;
    padding: 4px;
    margin: -4px;

    &::-webkit-scrollbar {
        display: none;
    }
}

.rail__card {
    flex: 0 0 var(--rail-card-width);
    scroll-snap-align: start;
    display: flex;
    flex-direction: column;
    gap: 8px;
    text-decoration: none;
    color: inherit;
    border-radius: var(--rail-radius);
    transition: transform 0.2s ease;

    &:hover {
        transform: translateY(-2px);
    }

    &:hover .rail__art {
        box-shadow: 0 10px 24px -12px rgba(0, 0, 0, 0.55);
    }
}

.rail__art {
    position: relative;
    overflow: hidden;
    border-radius: var(--rail-radius);
    background: var(--mat-sys-surface-container);
    transition: box-shadow 0.2s ease;

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
    }
}

.rail__art-fallback {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(
        135deg,
        color-mix(
                in srgb,
                var(--mat-sys-primary) 12%,
                var(--mat-sys-surface-container)
            )
            0%,
        var(--mat-sys-surface-container) 100%
    );

    mat-icon {
        font-size: 44px;
        width: 44px;
        height: 44px;
        color: color-mix(
            in srgb,
            var(--mat-sys-primary) 70%,
            var(--mat-sys-on-surface-variant)
        );
        opacity: 0.6;
    }
}

.rail__meta {
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 0 2px;
    min-width: 0;
}

.rail__card-title {
    font-size: 0.85rem;
    font-weight: 500;
    color: var(--mat-sys-on-surface);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.rail__card-subtitle {
    font-size: 0.72rem;
    color: var(--mat-sys-on-surface-variant);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    opacity: 0.8;
}

.rail__chev {
    position: absolute;
    top: 0;
    bottom: calc(100% - var(--rail-card-width) * 1.5);
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: calc(var(--rail-card-width) * 1.5);
    border: 0;
    border-radius: 10px;
    background: color-mix(in srgb, var(--mat-sys-surface) 85%, transparent);
    backdrop-filter: blur(8px);
    color: var(--mat-sys-on-surface);
    cursor: pointer;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.15s ease;
    z-index: 2;
    box-shadow: 0 4px 12px -4px rgba(0, 0, 0, 0.3);

    mat-icon {
        font-size: 22px;
        width: 22px;
        height: 22px;
    }

    &:hover {
        background: var(--mat-sys-surface-container-high);
    }

    &--left {
        left: -6px;
    }

    &--right {
        right: -6px;
    }
}

@media (hover: none) {
    .rail__chev {
        display: none;
    }
}

@media (max-width: 720px) {
    :host {
        --rail-card-width: 136px;
    }
}

