:host {
    display: block;
    padding: 20px;
    box-sizing: border-box;
    min-height: 100%;
}

.rails-page {
    max-width: 1440px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 28px;
    min-width: 0;
}

// ── Hero ────────────────────────────────────────────────────────────────────
.hero {
    display: grid;
    grid-template-columns: minmax(0, 280px) minmax(0, 1fr);
    gap: 20px;
    text-decoration: none;
    color: inherit;
    border-radius: 20px;
    padding: 16px;
    background: linear-gradient(
        135deg,
        color-mix(in srgb, var(--mat-sys-primary) 18%, var(--mat-sys-surface-container-high))
            0%,
        var(--mat-sys-surface-container-high) 100%
    );
    border: 1px solid color-mix(in srgb, var(--mat-sys-primary) 20%, var(--mat-sys-outline-variant));
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;

    &:hover {
        transform: translateY(-2px);
        box-shadow: 0 18px 36px -24px color-mix(in srgb, var(--mat-sys-primary) 60%, black);
    }
}

.hero__art {
    position: relative;
    aspect-ratio: 16 / 9;
    border-radius: 14px;
    overflow: hidden;
    background: var(--mat-sys-surface-container);

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
    }
}

.hero__art-fallback {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;

    mat-icon {
        font-size: 56px;
        width: 56px;
        height: 56px;
        color: var(--mat-sys-primary);
        opacity: 0.7;
    }
}

.hero__body {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 6px;
    min-width: 0;
}

.hero__eyebrow {
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--mat-sys-primary);
    opacity: 0.85;
}

.hero__title {
    margin: 0;
    font-size: 1.6rem;
    font-weight: 600;
    letter-spacing: -0.02em;
    color: var(--mat-sys-on-surface);
    overflow: hidden;
    text-overflow: ellipsis;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
}

.hero__subtitle {
    margin: 0;
    font-size: 0.88rem;
    color: var(--mat-sys-on-surface-variant);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.hero__cta {
    margin-top: 10px;
    align-self: flex-start;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 16px 8px 12px;
    border-radius: 999px;
    background: var(--mat-sys-primary);
    color: var(--mat-sys-on-primary);
    font-size: 0.85rem;
    font-weight: 600;

    mat-icon {
        font-size: 20px;
        width: 20px;
        height: 20px;
    }
}

// ── Loading skeleton ────────────────────────────────────────────────────────
.rails-page__skeleton {
    display: flex;
    flex-direction: column;
    gap: 28px;
}

.skeleton {
    border-radius: 18px;
    background: linear-gradient(
        90deg,
        var(--mat-sys-surface-container) 0%,
        var(--mat-sys-surface-container-high) 50%,
        var(--mat-sys-surface-container) 100%
    );
    background-size: 200% 100%;
    animation: shimmer 1.6s linear infinite;
}

.skeleton--hero {
    height: 200px;
}

.skeleton--rail {
    height: 280px;
}

@keyframes shimmer {
    from {
        background-position: 200% 0;
    }
    to {
        background-position: -200% 0;
    }
}

// ── Responsive ──────────────────────────────────────────────────────────────
@media (max-width: 720px) {
    :host {
        padding: 14px;
    }

    .hero {
        grid-template-columns: 1fr;
        gap: 14px;
    }

    .hero__title {
        font-size: 1.2rem;
    }
}

