:host {
    display: block;
    --rail-card-width: 172px;
    --rail-gap: 14px;
    --rail-radius: 12px;
}

.rail {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.rail__header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    padding: 0 2px;
}

.rail__title {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: var(--app-heading-color, #1a1d23);
}

.rail__see-all {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    font-size: 0.78rem;
    font-weight: 500;
    color: var(--app-muted-color, #8891a4);
    text-decoration: none;
    transition: color 0.15s ease;

    mat-icon {
        font-size: 16px;
        width: 16px;
        height: 16px;
    }

    &:hover {
        color: var(--app-selection-color, #2f7bff);
    }
}

.rail__viewport {
    position: relative;
    min-width: 0;

    &:hover .rail__chev--visible {
        opacity: 1;
        pointer-events: auto;
    }
}

.rail__track {
    display: flex;
    align-items: flex-start;
    gap: var(--rail-gap);
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x mandatory;
    scroll-padding-inline-start: 4px;
    scrollbar-width: none;
    padding: 4px;
    margin: -4px;

    &::-webkit-scrollbar {
        display: none;
    }
}

.rail__card {
    flex: 0 0 var(--rail-card-width);
    scroll-snap-align: start;
    display: flex;
