cat > /tmp/prune-i18n.mjs <<'EOF'
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const LIVE_KEYS = new Set([
  'CONTINUE_WATCHING',
  'RECENTLY_WATCHED',
  'GLOBAL_FAVORITES',
  'RECENT_SOURCES',
  'MANAGE_ALL',
  'UNTITLED_SOURCE',
  'STALKER_PORTAL',
  'STALKER',
  'XTREAM',
  'M3U',
  'PROVIDER',
  'NOT_YET_SYNCED',
  'TYPE_LIVE',
  'TYPE_MOVIE',
  'TYPE_SERIES',
  'REMOVE_FROM_HISTORY',
  'NO_HISTORY',
  'NO_HISTORY_HINT',
]);

const dir = '/Users/4gray/Code/iptvnator/apps/web/src/assets/i18n';
const files = readdirSync(dir).filter(f => f.endsWith('.json'));

let totalRemoved = 0;
for (const f of files) {
  const path = join(dir, f);
  const raw = readFileSync(path, 'utf8');
  const json = JSON.parse(raw);
  const dashboard = json?.WORKSPACE?.DASHBOARD;
  if (!dashboard) { console.log(`${f}: no WORKSPACE.DASHBOARD block`); continue; }
  const before = Object.keys(dashboard).length;
  const kept = {};
  for (const [k, v] of Object.entries(dashboard)) {
    if (LIVE_KEYS.has(k)) kept[k] = v;
  }
  json.WORKSPACE.DASHBOARD = kept;
  const removed = before - Object.keys(kept).length;
  totalRemoved += removed;
  writeFileSync(path, JSON.stringify(json, null, 4) + '\n');
  console.log(`${f}: removed ${removed} keys (${before} -> ${Object.keys(kept).length})`);
}
console.log(`\nTotal keys removed across ${files.length} files: ${totalRemoved}`);
EOF
