:host {
    display: block;
    --rail-card-width: 172px;
    --rail-gap: 14px;
    --rail-radius: 12px;
}

.rail {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.rail__header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    padding: 0 2px;
}

.rail__title {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: var(--app-heading-color, #1a1d23);
}

.rail__see-all {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    font-size: 0.78rem;
    font-weight: 500;
    color: var(--app-muted-color, #8891a4);
    text-decoration: none;
    transition: color 0.15s ease;

    mat-icon {
        font-size: 16px;
        width: 16px;
        height: 16px;
    }

    &:hover {
        color: var(--app-selection-color, #2f7bff);
    }
}

.rail__viewport {
    position: relative;
    min-width: 0;

    &:hover .rail__chev--visible {
        opacity: 1;
        pointer-events: auto;
    }
}

.rail__track {
    display: flex;
    align-items: flex-start;
    gap: var(--rail-gap);
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x mandatory;
    scroll-padding-inline-start: 4px;
    scrollbar-width: none;
    padding: 4px;
    margin: -4px;

    &::-webkit-scrollbar {
        display: none;
    }
}

.rail__card {
    flex: 0 0 var(--rail-card-width);
    scroll-snap-align: start;
    display: flex;
    flex-direction: column;
    gap: 8px;
    text-decoration: none;
    color: inherit;
    border-radius: var(--rail-radius);
    transition:
        transform 0.2s ease,
        filter 0.2s ease;

    &:hover {
        transform: translateY(-2px);

        .rail__art {
            box-shadow:
                0 12px 22px -12px rgba(0, 0, 0, 0.45),
                0 0 0 1px var(--app-selection-border, rgba(47, 123, 255, 0.4));
        }

        .rail__card-title {
            color: var(--app-selection-color, #2f7bff);
        }
    }
}

.rail__art {
    position: relative;
    overflow: hidden;
    border-radius: var(--rail-radius);
    background: var(--app-widget-bg, #1e2330);
    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.05));
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
    transition: box-shadow 0.2s ease;

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
    }
}

.rail__art-fallback {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background:
        radial-gradient(
            circle at 30% 20%,
            var(--app-selection-surface, rgba(120, 173, 255, 0.18)) 0%,
            transparent 55%
        ),
        var(--app-widget-bg, #1e2330);

    mat-icon {
        font-size: 44px;
        width: 44px;
        height: 44px;
        color: var(--app-selection-color, #78adff);
        opacity: 0.55;
    }
}

.rail__meta {
    display: flex;
    flex-direction: column;
    gap: 3px;
    padding: 0 2px;
    min-width: 0;
}

.rail__card-title {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--app-heading-color, #1a1d23);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    letter-spacing: -0.005em;
    transition: color 0.15s ease;
}

.rail__card-subtitle {
    font-size: 0.72rem;
    font-weight: 500;
    color: var(--app-muted-color, #8891a4);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.rail__chev {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 48px;
    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.08));
    border-radius: 10px;
    background: var(--app-widget-bg, #1e2330);
    backdrop-filter: blur(10px);
    color: var(--app-heading-color, #e6e1e5);
    cursor: pointer;
    opacity: 0;
    pointer-events: none;
    transition:
        opacity 0.15s ease,
        background-color 0.15s ease,
        transform 0.15s ease;
    z-index: 2;
    box-shadow: 0 6px 14px -6px rgba(0, 0, 0, 0.5);

    mat-icon {
        font-size: 22px;
        width: 22px;
        height: 22px;
    }

    &:hover {
        background: var(--app-card-hover-bg, #252b3a);
        transform: translateY(-50%) scale(1.05);
    }

    &--left {
        left: -4px;
    }

    &--right {
        right: -4px;
    }
}

@media (hover: none) {
    .rail__chev {
        display: none;
    }
}

@media (max-width: 720px) {
    :host {
        --rail-card-width: 140px;
    }
}

