// Clear CDP viewport emulation override.
// We lazy-load the `ws` package from node_modules of the repo (it's a common
// transitive dep in electron/karma stacks).
import { WebSocket } from 'ws';

const WS_URL = 'ws://127.0.0.1:9222/devtools/page/FFA6F1AFC7A3C3AAE26D121A88DF5420';
const ws = new WebSocket(WS_URL);
let id = 0;
const send = (method, params = {}) => new Promise((res, rej) => {
  const cmdId = ++id;
  const handler = (data) => {
    const msg = JSON.parse(data.toString());
    if (msg.id === cmdId) { ws.off('message', handler); msg.error ? rej(msg.error) : res(msg.result); }
  };
  ws.on('message', handler);
  ws.send(JSON.stringify({ id: cmdId, method, params }));
});
ws.on('open', async () => {
  await send('Emulation.clearDeviceMetricsOverride');
  console.log('Cleared device metrics override.');
  ws.close();
});
ws.on('error', (e) => { console.error('err:', e.message); process.exit(1); });
EOF
