1	import {
2	    computed,
3	    DestroyRef,
4	    effect,
5	    inject,
6	    Injectable,
7	    signal,
8	} from '@angular/core';
9	import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
10	import { NavigationEnd, Router } from '@angular/router';
11	import { Store } from '@ngrx/store';
12	import {
13	    PlaylistActions,
14	    selectActivePlaylistId,
15	    selectAllPlaylistsMeta,
16	    selectPlaylistsLoadingFlag,
17	} from 'm3u-state';
18	import { filter } from 'rxjs';
19	import { PlaylistMeta } from 'shared-interfaces';
20	import {
21	    PortalProvider,
22	    PortalRailSection,
23	} from '@iptvnator/portal/shared/util';
24	
25	export interface PlaylistRouteContext {
26	    inWorkspace: boolean;
27	    provider: PortalProvider | null;
28	    playlistId: string | null;
29	    section: PortalRailSection | null;
30	}
31	
32	type PlaylistSectionMemory = {
33	    providers: Partial<Record<PortalProvider, string>>;
34	    playlists: Record<
35	        string,
36	        {
37	            provider: PortalProvider;
38	            section: string;
39	            updatedAt: number;
40	        }
41	    >;
42	};
43	
44	const LAST_SECTION_STORAGE_KEY = 'playlist-switcher:last-sections:v2';
45	const LEGACY_LAST_SECTION_STORAGE_KEY = 'playlist-switcher:last-sections';
46	const LAST_ACTIVE_PLAYLIST_STORAGE_KEY =
47	    'playlist-switcher:last-active-playlist-id';
48	const XTREAM_SECTIONS = [
49	    'live',
50	    'vod',
51	    'series',
52	    'favorites',
53	    'recent',
54	    'search',
55	    'recently-added',
56	    'downloads',
57	] as const;
58	const STALKER_SECTIONS = [
59	    'itv',
60	    'vod',
61	    'series',
62	    'favorites',
63	    'recent',
64	    'search',
65	    'downloads',
66	] as const;
67	const M3U_SECTIONS = ['all', 'groups', 'favorites', 'recent'] as const;
68	
69	@Injectable({ providedIn: 'root' })
70	export class PlaylistContextFacade {
71	    private readonly destroyRef = inject(DestroyRef);
72	    private readonly router = inject(Router);
73	    private readonly store = inject(Store);
74	
75	    readonly playlists = this.store.selectSignal(selectAllPlaylistsMeta);
76	    readonly allPlaylistsLoaded = this.store.selectSignal(
77	        selectPlaylistsLoadingFlag
78	    );
79	    readonly activePlaylistId = this.store.selectSignal(selectActivePlaylistId);
80	
81	    readonly currentUrl = signal(this.router.url);
82	    readonly routeContext = computed(() =>
83	        this.getRouteContext(this.currentUrl())
84	    );
85	    readonly routeProvider = computed(() => this.routeContext().provider);
86	    readonly routePlaylistId = computed(() => this.routeContext().playlistId);
87	    readonly routeSection = computed(() => this.routeContext().section);
88	    readonly resolvedPlaylistId = computed(() => {
89	        const routePlaylistId = this.routePlaylistId();
90	        if (routePlaylistId) {
91	            return routePlaylistId;
92	        }
93	
94	        const activePlaylistId = this.activePlaylistId();
95	        return activePlaylistId || null;
96	    });
97	    readonly activePlaylist = computed(() => {
98	        const playlistId = this.resolvedPlaylistId();
99	        if (!playlistId) {
100	            return null;
101	        }
102	
103	        return (
104	            this.playlists().find((playlist) => playlist._id === playlistId) ??
105	            null
106	        );
107	    });
108	    readonly activeProvider = computed(() => {
109	        const playlist = this.activePlaylist();
110	        return playlist ? this.getProviderForPlaylist(playlist) : null;
111	    });
112	
113	    constructor() {
114	        this.clearLegacySectionMemory();
115	        this.syncFromUrl(this.router.url);
116	
117	        effect(() => {
118	            const allPlaylistsLoaded = this.allPlaylistsLoaded();
119	            const playlistIds = this.playlists().map(
120	                (playlist) => playlist._id
121	            );
122	            const playlistIdSet = new Set(playlistIds);
123	            const selectedId = this.activePlaylistId() || null;
124	            const routeId = this.routePlaylistId();
125	            const storedId = this.readPersistedActivePlaylistId();
126	
127	            if (!allPlaylistsLoaded) {
128	                if (routeId) {
129	                    this.writePersistedActivePlaylistId(routeId);
130	                    return;
131	                }
132	
133	                if (selectedId) {
134	                    this.writePersistedActivePlaylistId(selectedId);
135	                }
136	
137	                return;
138	            }
139	
140	            this.removeDeletedPlaylistsFromSectionMemory(playlistIds);
141	
142	            if (routeId && playlistIdSet.has(routeId)) {
143	                this.writePersistedActivePlaylistId(routeId);
144	                return;
145	            }
146	
147	            if (selectedId && playlistIdSet.has(selectedId)) {
148	                this.writePersistedActivePlaylistId(selectedId);
149	                return;
150	            }
151	
152	            if (
153	                !routeId &&
154	                !selectedId &&
155	                storedId &&
156	                playlistIdSet.has(storedId)
157	            ) {
158	                this.activatePlaylist(storedId);
159	                return;
160	            }
161	
162	            if (storedId && !playlistIdSet.has(storedId)) {
163	                this.clearPersistedActivePlaylistId();
164	            }
165	        });
166	
167	        this.router.events
168	            .pipe(
169	                filter(
170	                    (event): event is NavigationEnd =>
171	                        event instanceof NavigationEnd
172	                ),
173	                takeUntilDestroyed(this.destroyRef)
174	            )
175	            .subscribe((event) => {
176	                this.syncFromUrl(event.urlAfterRedirects);
177	            });
178	    }
179	
180	    syncFromUrl(url = this.router.url): PlaylistRouteContext {
181	        this.currentUrl.set(url);
182	        const routeContext = this.routeContext();
183	
184	        this.rememberSection(routeContext);
185	
186	        if (routeContext.playlistId) {
187	            this.activatePlaylist(routeContext.playlistId);
188	        }
189	
190	        return routeContext;
191	    }
192	
193	    activatePlaylist(playlistId: string): void {
194	        if (!playlistId || this.activePlaylistId() === playlistId) {
195	            return;
196	        }
197	
198	        this.store.dispatch(PlaylistActions.setActivePlaylist({ playlistId }));
199	    }
200	
201	    selectPlaylist(playlist: PlaylistMeta): void {
202	        const routeContext = this.routeContext();
203	        const provider = this.getProviderForPlaylist(playlist);
204	
205	        this.activatePlaylist(playlist._id);
206	
207	        const targetCommands = this.resolveTargetCommands(
208	            provider,
209	            playlist._id,
210	            routeContext
211	        );
212	
213	        if (targetCommands) {
214	            void this.router.navigate(targetCommands);
215	        }
216	    }
217	
218	    resolveTargetCommands(
219	        provider: PortalProvider,
220	        playlistId: string,
221	        routeContext = this.routeContext()
222	    ): string[] | null {
223	        const prefix = routeContext.inWorkspace ? ['workspace'] : [];
224	
225	        if (routeContext.inWorkspace && !routeContext.provider) {
226	            return null;
227	        }
228	
229	        if (provider === 'playlists') {
230	            const section = this.resolveTargetSection(
231	                provider,
232	                routeContext.section,
233	                playlistId
234	            );
235	            return [...prefix, 'playlists', playlistId, section];
236	        }
237	
238	        if (!this.supportsSectionNavigation(provider)) {
239	            return [...prefix, provider, playlistId];
240	        }
241	
242	        const section = this.resolveTargetSection(
243	            provider,
244	            routeContext.section,
245	            playlistId
246	        );
247	        return [...prefix, provider, playlistId, section];
248	    }
249	
250	    getProviderForPlaylist(playlist: PlaylistMeta): PortalProvider {
251	        if (playlist.serverUrl) {
252	            return 'xtreams';
253	        }
254	        if (playlist.macAddress) {
255	            return 'stalker';
256	        }
257	        return 'playlists';
258	    }
259	
260	    private isWorkspaceRoute(url: string): boolean {
261	        return /^\/workspace(?:\/|$)/.test(url);
262	    }
263	
