@if (hero(); as item) {
    <a
        class="hero"
        [routerLink]="heroLink(item)"
        [state]="heroState(item) ?? {}"
    >
        <span class="hero__art">
            @if (item.poster_url) {
                <img
                    [src]="item.poster_url"
                    [alt]="item.title"
                    loading="eager"
                    decoding="async"
                />
            } @else {
                <span class="hero__art-fallback">
                    <mat-icon>{{ heroIcon(item) }}</mat-icon>
                </span>
            }
        </span>

        <span class="hero__body">
            <span class="hero__eyebrow">{{ heroEyebrow() }}</span>
            <h1 class="hero__title">{{ item.title }}</h1>
            <p class="hero__subtitle">{{ heroSubtitle(item) }}</p>

            <span class="hero__cta">
                <mat-icon>play_arrow</mat-icon>
                <span>{{
                    'WORKSPACE.DASHBOARD.CONTINUE_WATCHING' | translate
                }}</span>
            </span>
        </span>
    </a>
}

