// ── Hero ────────────────────────────────────────────────────────────────────
// Netflix/Apple TV-style hero: blurred poster backdrop + vignette + sharp
// 2:3 poster card + text block. Mirrors the pattern in
// libs/ui/components/src/lib/content-hero when no dedicated backdrop asset
// exists (we reuse the poster, blurred and scaled).
.hero {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, var(--hero-poster-width)) minmax(0, 1fr);
    gap: 24px;
    padding: 20px;
    text-decoration: none;
    color: inherit;
    border-radius: 20px;
    overflow: hidden;
    isolation: isolate;
    background: var(--app-widget-header-bg, #232840);
    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.08));
    box-shadow:
        0 1px 2px rgba(0, 0, 0, 0.2),
        0 12px 32px -18px var(--app-selection-glow, rgba(120, 173, 255, 0.4));
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;

    --hero-poster-width: 160px;

    &:hover {
        transform: translateY(-2px);
        box-shadow:
            0 1px 2px rgba(0, 0, 0, 0.2),
            0 20px 40px -20px var(--app-selection-glow, rgba(120, 173, 255, 0.55));
    }

    // No-image fallback: keep the accent gradient so the hero never looks flat.
    &:not(.hero--with-image) {
        background:
            var(
                --app-accent-gradient,
                linear-gradient(
                    135deg,
                    rgba(99, 102, 241, 0.12) 0%,
                    rgba(168, 85, 247, 0.07) 100%
                )
            ),
            var(--app-widget-header-bg, #232840);
    }
}

// Layer 0: blurred poster, scaled up to hide edges from the blur filter.
.hero__backdrop {
    position: absolute;
    inset: 0;
    background-size: cover;
    background-position: center 30%;
    background-repeat: no-repeat;
    filter: blur(36px) saturate(1.25);
    transform: scale(1.35);
    opacity: 0.55;
    z-index: 0;
    pointer-events: none;
}

// Layer 1: vignette that darkens the right side so the title + CTA are
// legible over bright backdrops. Also fades the left into the poster card.
.hero__vignette {
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background:
        linear-gradient(
            90deg,
            color-mix(in srgb, var(--app-widget-header-bg, #232840) 72%, transparent)
                0%,
            color-mix(in srgb, var(--app-widget-header-bg, #232840) 55%, transparent)
                40%,
            color-mix(in srgb, var(--app-widget-header-bg, #232840) 88%, transparent)
                100%
        ),
        linear-gradient(
            to bottom,
            transparent 0%,
            color-mix(in srgb, var(--app-widget-header-bg, #232840) 45%, transparent)
                100%
        );
}

// Layer 2: sharp poster in its native 2:3 aspect.
.hero__poster {
    position: relative;
    z-index: 2;
    width: var(--hero-poster-width);
    aspect-ratio: 2 / 3;
    border-radius: 12px;
    overflow: hidden;
    background: var(--app-widget-bg, #1e2330);
    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.1));
    box-shadow: 0 8px 24px -10px rgba(0, 0, 0, 0.55);
    align-self: center;

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
    }
}

.hero__poster-fallback {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background:
        radial-gradient(
            circle at 50% 40%,
            var(--app-selection-surface, rgba(120, 173, 255, 0.2)) 0%,
            transparent 60%
        );

    mat-icon {
        font-size: 56px;
        width: 56px;
        height: 56px;
        color: var(--app-selection-color, #78adff);
        opacity: 0.75;
    }
}

.hero__body {
    position: relative;
    z-index: 2;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 6px;
    min-width: 0;
}

.hero__eyebrow {
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--app-eyebrow-color, #6b7494);
    // On image heroes the eyebrow sits over the vignette; bump contrast.
    .hero--with-image & {
        color: color-mix(
            in srgb,
            var(--app-selection-color, #78adff) 70%,
            var(--app-eyebrow-color, #6b7494)
        );
        text-shadow: 0 1px 6px rgba(0, 0, 0, 0.4);
    }
}

.hero__title {
    margin: 4px 0 2px;
    font-size: 1.7rem;
    font-weight: 600;
    line-height: 1.15;
    letter-spacing: -0.02em;
    color: var(--app-heading-color, #d8dce8);
    overflow: hidden;
    text-overflow: ellipsis;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;

    .hero--with-image & {
        color: #fff;
        text-shadow: 0 2px 12px rgba(0, 0, 0, 0.55);
    }
}

.hero__subtitle {
    margin: 0;
    font-size: 0.88rem;
    font-weight: 500;
    color: var(--app-body-color, #8b93a8);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;

    .hero--with-image & {
        color: rgba(255, 255, 255, 0.82);
        text-shadow: 0 1px 6px rgba(0, 0, 0, 0.45);
    }
}

.hero__cta {
    margin-top: 14px;
    align-self: flex-start;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 9px 18px 9px 14px;
    border-radius: 999px;
    background: var(--app-selection-color, #78adff);
    color: var(--app-selection-on-color, #071225);
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 0.005em;
    box-shadow: 0 4px 12px -4px var(--app-selection-glow, rgba(120, 173, 255, 0.5));

    mat-icon {
        font-size: 20px;
        width: 20px;
        height: 20px;
    }
}

