async addToFavorites(
    contentId: number,
    playlistId: string
): Promise<boolean> {
    try {
        await window.electron.dbAddFavorite(contentId, playlistId);
        return true;
    } catch (error) {
        console.error('Error adding to favorites:', error);
        return false;
    }
}

