import { and, asc, desc, eq, inArray, sql } from 'drizzle-orm';
import * as schema from 'database-schema';
import type { AppDatabase } from '../database.types';
import {
    chunkValues,
    checkpointOperation,
    type OperationControl,
    reportOperationProgress,
} from './operation-control';

const DEFAULT_BATCH_SIZE = 100;

export async function addFavorite(
    db: AppDatabase,
    contentId: number,
    playlistId: string,
    options?: { backdropUrl?: string }
): Promise<{ success: boolean }> {
    await db.insert(schema.favorites).values({
        contentId,
        playlistId,
    });

    await upsertContentBackdrop(db, contentId, options?.backdropUrl);

    return { success: true };
}

// Lazy-persists a backdrop URL onto the content row if it's not already set.
// Called from the favorite/recent write paths so the dashboard hero can later
// surface a cinematic backdrop without a separate API round-trip.
async function upsertContentBackdrop(
    db: AppDatabase,
    contentId: number,
    backdropUrl?: string
): Promise<void> {
    if (!backdropUrl) {
        return;
    }

    await db
        .update(schema.content)
        .set({ backdropUrl })
        .where(
            and(
                eq(schema.content.id, contentId),
                sql`(${schema.content.backdropUrl} IS NULL OR ${schema.content.backdropUrl} = '')`
            )
        );
}

export async function removeFavorite(
    db: AppDatabase,
    contentId: number,
    playlistId: string
): Promise<{ success: boolean }> {
    await db
        .delete(schema.favorites)
        .where(
            and(
                eq(schema.favorites.contentId, contentId),
                eq(schema.favorites.playlistId, playlistId)
            )
        );

    return { success: true };
}

export async function isFavorite(
    db: AppDatabase,
    contentId: number,
    playlistId: string
): Promise<boolean> {
    const result = await db
        .select({ count: sql<number>`count(*)` })
        .from(schema.favorites)
        .where(
            and(
                eq(schema.favorites.contentId, contentId),
                eq(schema.favorites.playlistId, playlistId)
            )
        );

    return result[0].count > 0;
}

export async function getFavorites(db: AppDatabase, playlistId: string) {
    return db
        .select({
            id: schema.content.id,
            category_id: schema.content.categoryId,
            title: schema.content.title,
            rating: schema.content.rating,
            added: schema.content.added,
            poster_url: schema.content.posterUrl,
            xtream_id: schema.content.xtreamId,
            type: schema.content.type,
            added_at: schema.favorites.addedAt,
            position: schema.favorites.position,
        })
        .from(schema.favorites)
        .innerJoin(
            schema.content,
            eq(schema.favorites.contentId, schema.content.id)
        )
        .where(eq(schema.favorites.playlistId, playlistId))
        .orderBy(
            asc(schema.favorites.position),
            desc(schema.favorites.addedAt)
        );
}

export async function getGlobalFavorites(db: AppDatabase) {
    return db
        .select({
            id: schema.content.id,
            category_id: schema.content.categoryId,
            title: schema.content.title,
            rating: schema.content.rating,
            added: schema.content.added,
            poster_url: schema.content.posterUrl,
            xtream_id: schema.content.xtreamId,
            type: schema.content.type,
            playlist_id: schema.playlists.id,
            playlist_name: schema.playlists.name,
            added_at: schema.favorites.addedAt,
            position: schema.favorites.position,
        })
        .from(schema.favorites)
        .innerJoin(
            schema.content,
            eq(schema.favorites.contentId, schema.content.id)
        )
        .innerJoin(
            schema.categories,
            eq(schema.content.categoryId, schema.categories.id)
        )
        .innerJoin(
            schema.playlists,
            eq(schema.categories.playlistId, schema.playlists.id)
        )
        .where(eq(schema.content.type, 'live'))
        .orderBy(asc(schema.favorites.position), desc(schema.favorites.addedAt))
        .limit(300);
}

export async function getAllGlobalFavorites(db: AppDatabase) {
    return db
        .select({
            id: schema.content.id,
            category_id: schema.content.categoryId,
            title: schema.content.title,
            rating: schema.content.rating,
            added: schema.content.added,
            poster_url: schema.content.posterUrl,
            xtream_id: schema.content.xtreamId,
            type: schema.content.type,
            playlist_id: schema.playlists.id,
            playlist_name: schema.playlists.name,
            added_at: schema.favorites.addedAt,
            position: schema.favorites.position,
        })
        .from(schema.favorites)
        .innerJoin(
            schema.content,
            eq(schema.favorites.contentId, schema.content.id)
        )
        .innerJoin(
            schema.categories,
            eq(schema.content.categoryId, schema.categories.id)
        )
        .innerJoin(
            schema.playlists,
            eq(schema.categories.playlistId, schema.playlists.id)
        )
        .orderBy(asc(schema.favorites.position), desc(schema.favorites.addedAt))
        .limit(500);
}

export async function reorderGlobalFavorites(
    db: AppDatabase,
    updates: { content_id: number; position: number }[],
    control?: OperationControl
): Promise<{ success: boolean }> {
    if (!Array.isArray(updates) || updates.length === 0) {
        return { success: true };
    }

    let current = 0;
    const total = updates.length;

    for (const chunk of chunkValues(updates, DEFAULT_BATCH_SIZE)) {
        await checkpointOperation(control);

        for (const { content_id, position } of chunk) {
            await db
                .update(schema.favorites)
                .set({ position })
                .where(eq(schema.favorites.contentId, content_id));
        }

        current += chunk.length;
        await reportOperationProgress(control, {
            phase: 'reordering-global-favorites',
            current,
            total,
            increment: chunk.length,
        });
    }

    return { success: true };
}

import { and, desc, eq, inArray, sql } from 'drizzle-orm';
import * as schema from 'database-schema';
import type { AppDatabase } from '../database.types';

export async function getRecentlyViewed(db: AppDatabase) {
    return db
        .select({
            id: schema.content.id,
            category_id: schema.content.categoryId,
            title: schema.content.title,
            rating: schema.content.rating,
            added: schema.content.added,
            poster_url: schema.content.posterUrl,
            xtream_id: schema.content.xtreamId,
            type: schema.content.type,
            playlist_id: schema.categories.playlistId,
            playlist_name: schema.playlists.name,
            viewed_at: schema.recentlyViewed.viewedAt,
        })
        .from(schema.recentlyViewed)
        .innerJoin(
            schema.content,
            eq(schema.recentlyViewed.contentId, schema.content.id)
        )
        .innerJoin(
            schema.categories,
            eq(schema.content.categoryId, schema.categories.id)
        )
        .innerJoin(
            schema.playlists,
            eq(schema.categories.playlistId, schema.playlists.id)
        )
        .orderBy(desc(schema.recentlyViewed.viewedAt))
        .limit(100);
}

export async function clearRecentlyViewed(
    db: AppDatabase
): Promise<{ success: boolean }> {
    await db.delete(schema.recentlyViewed);
    return { success: true };
}

export async function getRecentItems(
    db: AppDatabase,
    playlistId: string
) {
    return db
        .select({
            id: schema.content.id,
            category_id: schema.content.categoryId,
            title: schema.content.title,
            rating: schema.content.rating,
            added: schema.content.added,
            poster_url: schema.content.posterUrl,
            xtream_id: schema.content.xtreamId,
            type: schema.content.type,
            viewed_at: schema.recentlyViewed.viewedAt,
        })
        .from(schema.recentlyViewed)
        .innerJoin(
            schema.content,
            eq(schema.recentlyViewed.contentId, schema.content.id)
        )
        .where(eq(schema.recentlyViewed.playlistId, playlistId))
        .orderBy(desc(schema.recentlyViewed.viewedAt))
        .limit(100);
}

export async function addRecentItem(
    db: AppDatabase,
    contentId: number,
    playlistId: string,
    options?: { backdropUrl?: string }
): Promise<{ success: boolean }> {
    const existing = await db
        .select()
        .from(schema.recentlyViewed)
        .where(
            and(
                eq(schema.recentlyViewed.contentId, contentId),
                eq(schema.recentlyViewed.playlistId, playlistId)
            )
        )
        .limit(1);

    if (existing.length > 0) {
        await db
            .update(schema.recentlyViewed)
            .set({ viewedAt: sql`CURRENT_TIMESTAMP` })
            .where(
                and(
                    eq(schema.recentlyViewed.contentId, contentId),
                    eq(schema.recentlyViewed.playlistId, playlistId)
                )
            );
    } else {
        await db.insert(schema.recentlyViewed).values({
            contentId,
            playlistId,
        });
    }

    if (options?.backdropUrl) {
        await db
            .update(schema.content)
            .set({ backdropUrl: options.backdropUrl })
            .where(
                and(
                    eq(schema.content.id, contentId),
                    sql`(${schema.content.backdropUrl} IS NULL OR ${schema.content.backdropUrl} = '')`
                )
            );
    }

    return { success: true };
}

export async function clearPlaylistRecentItems(
    db: AppDatabase,
    playlistId: string
): Promise<{ success: boolean }> {
    const contentIds = await db
        .select({ id: schema.content.id })
        .from(schema.content)
        .innerJoin(
            schema.categories,
            eq(schema.content.categoryId, schema.categories.id)
        )
        .where(eq(schema.categories.playlistId, playlistId));

    if (contentIds.length > 0) {
        await db.delete(schema.recentlyViewed).where(
            inArray(
                schema.recentlyViewed.contentId,
                contentIds.map((content) => content.id)
            )
        );
    }

    return { success: true };
}

export async function removeRecentItem(
    db: AppDatabase,
    contentId: number,
    playlistId: string
): Promise<{ success: boolean }> {
    await db
        .delete(schema.recentlyViewed)
        .where(
            and(
                eq(schema.recentlyViewed.contentId, contentId),
                eq(schema.recentlyViewed.playlistId, playlistId)
            )
        );

    return { success: true };
}

