input.command:
agent-browser --cdp 9222 eval "(() => {
  const q = (sel) => {
    const el = document.querySelector(sel);
    if (!el) return null;
    const cs = getComputedStyle(el);
    return {
      size: cs.fontSize,
      weight: cs.fontWeight,
      lh: cs.lineHeight,
      ls: cs.letterSpacing,
    };
  };
  return JSON.stringify({
    railTitle: q('.rail__label'),
    railCount: q('.rail__count'),
    seeAll: q('.rail__see-all'),
    heroTitle: q('.hero__title'),
    heroCta: q('.hero__cta'),
    cardTitle: q('.rail__card-title'),
  }, null, 2);
})()"

