toolUseResult.originalFile:
:host {
    display: block;
    --rail-card-width: 172px;
    --rail-gap: 14px;
    --rail-radius: 12px;
}

.rail {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.rail__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 0 2px;
    // Tighter height cap — keeps rail chapter markers compact
    min-height: 24px;
}

.rail__title {
    margin: 0;
    display: inline-flex;
    align-items: baseline;
    gap: 8px;
    font-size: 1.125rem; // 18px — matches Netflix rail-title scale
    font-weight: 600;
    line-height: 1.2;
    letter-spacing: -0.012em;
    color: var(--app-heading-color, #1a1d23);
}

// Muted count badge, tabular numerals for alignment, sits just after label.
.rail__count {
    font-size: 0.78rem;
    font-weight: 500;
    line-height: 1;
    color: var(--app-muted-color, #8891a4);
    font-variant-numeric: tabular-nums;
    // Tiny capsule to read as a "count chip", not a number-in-text
    padding: 2px 8px;
    border-radius: 999px;
    background: color-mix(
        in srgb,
        var(--app-muted-color, #8891a4) 18%,
        transparent
    );
    letter-spacing: 0;
}

.rail__see-all {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    padding: 4px 8px 4px 10px;
    border-radius: 999px;
    font-size: 0.78rem;
    font-weight: 500;
    line-height: 1;
    letter-spacing: 0.005em;
    color: var(--app-muted-color, #8891a4);
    text-decoration: none;
    transition:
        color 0.15s ease,
        background-color 0.15s ease;

    mat-icon {
        font-size: 16px;
        width: 16px;
        height: 16px;
        transition: transform 0.15s ease;
    }

    &:hover {
        color: var(--app-selection-color, #2f7bff);
        background: color-mix(
            in srgb,
            var(--app-selection-color, #2f7bff) 12%,
            transparent
        );

        mat-icon {
            transform: translateX(2px);
        }
    }

    &:focus-visible {
        outline: 2px solid var(--app-selection-color, #2f7bff);
        outline-offset: 2px;
    }
}

.rail__viewport {
    position: relative;
    min-width: 0;

    &:hover .rail__chev--visible {
        opacity: 1;
        pointer-events: auto;
    }
}

.rail__track {
    display: flex;
    align-items: flex-start;
    gap: var(--rail-gap);
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x mandatory;
    scroll-padding-inline-start: 4px;
    scrollbar-width: none;
    padding: 4px;
    margin: -4px;

    &::-webkit-scrollbar {
        display: none;
    }
}

.rail__card {
