    }
}

.rail__meta {
    display: flex;
    flex-direction: column;
    gap: 3px;
    padding: 0 2px;
    min-width: 0;
}

.rail__card-title {
    font-size: 0.85rem;
    font-weight: 600;
    line-height: 1.3;
    color: var(--app-heading-color, #1a1d23);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    letter-spacing: -0.005em;
    transition: color 0.15s ease;
}

.rail__card-subtitle {
    font-size: 0.72rem;
    font-weight: 500;
    line-height: 1.4;
    color: var(--app-muted-color, #8891a4);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    letter-spacing: 0.005em;
}

.rail__chev {
    position: absolute;
