    opacity: 0;
    pointer-events: none;
    transition:
        opacity 0.15s ease,
        background-color 0.15s ease,
        transform 0.15s ease;
    z-index: 2;
    box-shadow: 0 6px 14px -6px rgba(0, 0, 0, 0.5);

    mat-icon {
        font-size: 22px;
        width: 22px;
        height: 22px;
    }

