1	import { Component, computed, inject } from '@angular/core';
2	import { ActivatedRoute, Router } from '@angular/router';
3	import { TranslatePipe } from '@ngx-translate/core';
4	import { ContentCardComponent } from '@iptvnator/portal/shared/ui';
5	import { XtreamStore } from '@iptvnator/portal/xtream/data-access';
6	import { ContentType } from '@iptvnator/portal/xtream/data-access';
7	
8	interface RecentlyAddedItem {
9	    readonly added?: string;
10	    readonly category_id: string | number;
11	    readonly cover?: string;
12	    readonly id?: number;
13	    readonly last_modified?: string;
14	    readonly name?: string;
15	    readonly poster_url?: string;
16	    readonly series_id?: number;
17	    readonly stream_id?: number;
18	    readonly stream_icon?: string;
19	    readonly title?: string;
20	    readonly xtream_id?: number;
21	}
22	
23	@Component({
24	    selector: 'app-recently-added',
25	    templateUrl: './recently-added.component.html',
26	    styleUrls: ['./recently-added.component.scss'],
27	    imports: [ContentCardComponent, TranslatePipe],
28	})
29	export class RecentlyAddedComponent {
30	    private readonly xtreamStore = inject(XtreamStore);
31	    private readonly router = inject(Router);
32	    private readonly activatedRoute = inject(ActivatedRoute);
33	
34	    readonly recentlyAddedLive = computed(() =>
35	        this.getRecentlyAdded(
36	            this.xtreamStore.liveStreams() as RecentlyAddedItem[]
37	        )
38	    );
39	    readonly recentlyAddedVod = computed(() =>
40	        this.getRecentlyAdded(
41	            this.xtreamStore.vodStreams() as RecentlyAddedItem[]
42	        )
43	    );
44	    readonly recentlyAddedSeries = computed(() =>
45	        this.getRecentlyAdded(
46	            this.xtreamStore.serialStreams() as RecentlyAddedItem[],
47	            true
48	        )
49	    );
50	    readonly selectedContentType = this.xtreamStore.selectedContentType;
51	
52	    private getRecentlyAdded<T extends RecentlyAddedItem>(
53	        items: T[],
54	        isSeries = false
55	    ): T[] {
56	        return [...items]
57	            .sort((a, b) => {
58	                const dateA =
59	                    parseInt(isSeries ? a.last_modified : a.added) || 0;
60	                const dateB =
61	                    parseInt(isSeries ? b.last_modified : b.added) || 0;
62	                return dateB - dateA;
63	            })
64	            .slice(0, 20);
65	    }
66	
67	    getDate(item: RecentlyAddedItem): number {
68	        const timestamp = item.added || item.last_modified;
69	        return parseInt(timestamp) * 1000;
70	    }
71	
72	    isSectionActive(type: ContentType): boolean {
73	        return this.selectedContentType() === type;
74	    }
75	
76	    openItem(item: RecentlyAddedItem, type: ContentType) {
77	        this.xtreamStore.setSelectedContentType(type);
78	
79	        if (type === 'live') {
80	            this.router.navigate(['..', type, item.category_id], {
81	                relativeTo: this.activatedRoute,
82	            });
83	        } else {
84	            const itemId =
85	                item.xtream_id ||
86	                item.id ||
87	                (type === 'series' ? item.series_id : item.stream_id);
88	            this.router.navigate(['..', type, item.category_id, itemId], {
89	                relativeTo: this.activatedRoute,
90	            });
91	        }
92	    }
93	}
