// ── Loading skeleton ────────────────────────────────────────────────────────
// Geometry mirrors the real hero + rails so the layout doesn't shift when
// data arrives. All shimmer targets share the `%skeleton-shimmer` placeholder
// defined below.
%skeleton-shimmer {
    background: linear-gradient(
        90deg,
        var(--app-widget-bg, #1e2330) 0%,
        var(--app-widget-header-bg, #232840) 50%,
        var(--app-widget-bg, #1e2330) 100%
    );
    background-size: 200% 100%;
    animation: dashboard-skeleton-shimmer 1.6s linear infinite;
    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.05));
}

@keyframes dashboard-skeleton-shimmer {
    from {
        background-position: 200% 0;
    }
    to {
        background-position: -200% 0;
    }
}

// ── Hero ghost ──────────────────────────────────────────────────────────────
.rails-page__skeleton-hero {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 160px) minmax(0, 1fr);
    gap: 24px;
    padding: 20px;
    border-radius: 18px;
    background: var(--app-widget-header-bg, #232840);
    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.08));
}

.rails-page__skeleton-hero-poster {
    @extend %skeleton-shimmer;
    width: 160px;
    aspect-ratio: 2 / 3;
    border-radius: 12px;
    align-self: center;
}

.rails-page__skeleton-hero-body {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 10px;
    min-width: 0;
}

.rails-page__skeleton-hero-eyebrow {
    @extend %skeleton-shimmer;
    width: 140px;
    height: 12px;
    border-radius: 4px;
}

.rails-page__skeleton-hero-title {
    @extend %skeleton-shimmer;
    width: 60%;
    height: 28px;
    border-radius: 6px;
}

.rails-page__skeleton-hero-title--short {
    width: 35%;
}

.rails-page__skeleton-hero-subtitle {
    @extend %skeleton-shimmer;
    width: 45%;
    height: 14px;
    border-radius: 4px;
    margin-top: 2px;
}

.rails-page__skeleton-hero-cta {
    @extend %skeleton-shimmer;
    width: 160px;
    height: 36px;
    border-radius: 999px;
    margin-top: 14px;
}

// ── Rail ghost ──────────────────────────────────────────────────────────────
.rails-page__skeleton-rail {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 12px 0 0;
}

.rails-page__skeleton-header {
    @extend %skeleton-shimmer;
    width: 180px;
    height: 22px;
    border-radius: 6px;
}

.rails-page__skeleton-track {
    display: flex;
    gap: 14px;
    padding: 4px 0 16px;
    overflow: hidden;
}

.rails-page__skeleton-card {
    @extend %skeleton-shimmer;
    // Matches the real .rail__card width (--rail-card-width: 172px) and
    // .rail__art aspect-ratio 2/3, so when cards arrive the geometry is
    // identical and there's no layout shift.
    flex: 0 0 172px;
    width: 172px;
    aspect-ratio: 2 / 3;
    border-radius: 12px;
}

@media (prefers-reduced-motion: reduce) {
    .rails-page__skeleton-hero-poster,
    .rails-page__skeleton-hero-eyebrow,
    .rails-page__skeleton-hero-title,
    .rails-page__skeleton-hero-subtitle,
    .rails-page__skeleton-hero-cta,
    .rails-page__skeleton-header,
    .rails-page__skeleton-card {
        animation: none;
        background-position: 0 0;
    }
}

