:host {
    display: block;
    padding: 24px 28px 40px;
    box-sizing: border-box;
    min-height: 100%;
}

.rails-page {
    max-width: 1440px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 32px;
    min-width: 0;
}

// ── Hero ────────────────────────────────────────────────────────────────────
// Netflix/Apple TV-style hero: blurred poster backdrop + vignette + sharp 2:3
// poster card + text block. Mirrors content-hero fallback (no dedicated
// backdrop asset available, so we reuse the poster blurred + scaled).
.hero {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, var(--hero-poster-width)) minmax(0, 1fr);
    gap: 24px;
    padding: 20px;
    text-decoration: none;
    color: inherit;
    border-radius: 18px;
    overflow: hidden;
    isolation: isolate;
    background: var(--app-widget-header-bg, #232840);
    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.08));
    box-shadow:
        0 1px 2px rgba(0, 0, 0, 0.2),
        0 12px 32px -18px var(--app-selection-glow, rgba(120, 173, 255, 0.4));
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;

    --hero-poster-width: 160px;

    &:hover {
        transform: translateY(-2px);
        box-shadow:
            0 1px 2px rgba(0, 0, 0, 0.2),
            0 20px 40px -20px var(--app-selection-glow, rgba(120, 173, 255, 0.55));
    }

    // No-image fallback keeps the accent gradient so the hero is never flat.
    &:not(.hero--with-image) {
        background:
            var(
                --app-accent-gradient,
                linear-gradient(
                    135deg,
                    rgba(99, 102, 241, 0.12) 0%,
                    rgba(168, 85, 247, 0.07) 100%
                )
            ),
            var(--app-widget-header-bg, #232840);
    }
}

// Layer 0: backdrop. Two modes:
//   (1) Real backdrop (`.hero--has-backdrop`): sharp wide image with no blur.
//   (2) Blurred-poster fallback: heavy blur + scale so the poster's colours
//       wash across the full panel without the portrait edges showing.
.hero__backdrop {
    position: absolute;
    inset: 0;
    background-size: cover;
    background-position: center 25%;
    background-repeat: no-repeat;
    z-index: 0;
    pointer-events: none;

    // Fallback: blurred poster.
    filter: blur(40px) saturate(1.5);
    transform: scale(1.5);
    opacity: 0.9;
}

.hero--has-backdrop .hero__backdrop {
    filter: none;
    transform: none;
    opacity: 1;
}

// Layer 1: vignette. Scrim behind the poster card (contrast) and on the
// right edge (text legibility). Middle stays mostly transparent so the
// backdrop colours show through. Darkens further when a sharp backdrop is
// present, since real photography has more focal variation than a blur wash.
.hero__vignette {
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background:
        linear-gradient(
            90deg,
            color-mix(
                    in srgb,
                    var(--app-widget-header-bg, #232840) 55%,
                    transparent
                )
                0%,
            color-mix(
                    in srgb,
                    var(--app-widget-header-bg, #232840) 10%,
                    transparent
                )
                45%,
            color-mix(
                    in srgb,
                    var(--app-widget-header-bg, #232840) 65%,
                    transparent
                )
                100%
        ),
        linear-gradient(
            to bottom,
            transparent 55%,
            color-mix(
                    in srgb,
                    var(--app-widget-header-bg, #232840) 35%,
                    transparent
                )
                100%
        );
}

.hero--has-backdrop .hero__vignette {
    background:
        linear-gradient(
            90deg,
            rgba(0, 0, 0, 0.55) 0%,
            rgba(0, 0, 0, 0.2) 35%,
            rgba(0, 0, 0, 0.78) 100%
        ),
        linear-gradient(
            to bottom,
            rgba(0, 0, 0, 0) 40%,
            rgba(0, 0, 0, 0.45) 100%
        );
}

// Layer 2: sharp poster in native 2:3 aspect (no more 16:9 crop).
.hero__poster {
    position: relative;
    z-index: 2;
    width: var(--hero-poster-width);
    aspect-ratio: 2 / 3;
    border-radius: 12px;
    overflow: hidden;
    background: var(--app-widget-bg, #1e2330);
    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.1));
    box-shadow: 0 8px 24px -10px rgba(0, 0, 0, 0.55);
    align-self: center;

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
    }
}

.hero__poster-fallback {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background:
        radial-gradient(
            circle at 50% 40%,
            var(--app-selection-surface, rgba(120, 173, 255, 0.2)) 0%,
            transparent 60%
        );

    mat-icon {
        font-size: 56px;
        width: 56px;
        height: 56px;
        color: var(--app-selection-color, #78adff);
        opacity: 0.75;
    }
}

.hero__body {
    position: relative;
    z-index: 2;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 6px;
    min-width: 0;
}

.hero__eyebrow {
    font-size: 0.7rem;
    font-weight: 700;
    line-height: 1.2;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: var(--app-eyebrow-color, #6b7494);

    .hero--with-image & {
        color: color-mix(
            in srgb,
            var(--app-selection-color, #78adff) 70%,
            var(--app-eyebrow-color, #6b7494)
        );
        text-shadow: 0 1px 6px rgba(0, 0, 0, 0.4);
    }
}

.hero__title {
    margin: 6px 0 4px;
    font-size: 1.75rem;
    font-weight: 600;
    line-height: 1.15;
    // Display-weight tracking: looser than -0.02em which crushes glyphs at
    // this size (~28px). Matches Apple TV+ "Up Next" card scale.
    letter-spacing: -0.015em;
    color: var(--app-heading-color, #d8dce8);
    overflow: hidden;
    text-overflow: ellipsis;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;

    .hero--with-image & {
        color: #fff;
        text-shadow: 0 2px 12px rgba(0, 0, 0, 0.55);
    }
}

.hero__subtitle {
    margin: 0;
    font-size: 0.88rem;
    font-weight: 500;
    line-height: 1.45;
    letter-spacing: 0.002em;
    color: var(--app-body-color, #8b93a8);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;

    .hero--with-image & {
        color: rgba(255, 255, 255, 0.82);
        text-shadow: 0 1px 6px rgba(0, 0, 0, 0.45);
    }
}

.hero__cta {
    margin-top: 16px;
    align-self: flex-start;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 10px 20px 10px 14px;
    border-radius: 999px;
    background: var(--app-selection-color, #78adff);
    color: var(--app-selection-on-color, #071225);
    font-size: 0.875rem;
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.005em;
    // Explicit min-height anchors the text baseline regardless of font-smoothing
    min-height: 36px;
    box-sizing: border-box;
    box-shadow: 0 4px 12px -4px var(--app-selection-glow, rgba(120, 173, 255, 0.5));

    mat-icon {
        font-size: 20px;
        width: 20px;
        height: 20px;
        line-height: 20px;
    }
}

// ── Loading skeleton ────────────────────────────────────────────────────────
.rails-page__skeleton {
    display: flex;
    flex-direction: column;
    gap: 32px;
}

.skeleton {
    border-radius: 16px;
    background: linear-gradient(
        90deg,
        var(--app-widget-bg, #1e2330) 0%,
        var(--app-widget-header-bg, #232840) 50%,
        var(--app-widget-bg, #1e2330) 100%
    );
    background-size: 200% 100%;
    animation: shimmer 1.6s linear infinite;
}

.skeleton--hero {
    height: 190px;
}

.skeleton--rail {
    height: 260px;
}

@keyframes shimmer {
    from {
        background-position: 200% 0;
    }
    to {
        background-position: -200% 0;
    }
}

// ── Responsive ──────────────────────────────────────────────────────────────
@media (max-width: 720px) {
    :host {
        padding: 16px 16px 32px;
    }

    .rails-page {
        gap: 24px;
    }

    .hero {
        --hero-poster-width: 120px;
        grid-template-columns: var(--hero-poster-width) minmax(0, 1fr);
        gap: 14px;
        padding: 14px;
    }

    .hero__title {
        font-size: 1.3rem;
    }
}

