// Backdrop-agnostic chip (Netflix / Apple TV+ pattern). One rule handles
// dark and light themes, any poster colour, the no-image fallback — because
// the dark glass + border + white text are self-contained. Matches the
// chevron treatment on the rails for a consistent visual vocabulary.
.hero__eyebrow {
    align-self: flex-start;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 4px 10px;
    border-radius: 999px;
    background: rgba(0, 0, 0, 0.55);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.14);
    font-size: 0.68rem;
    font-weight: 700;
    line-height: 1;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #fff;
    // `margin-bottom` tightens the stack so the title doesn't feel orphaned
    // from the chip now that the chip has its own vertical footprint.
    margin-bottom: 2px;
}

